// Pad any lesson under 8 questions with fresh vocab questions (deduped by stem).
for (const u of preKMath.units) {
  for (const l of u.lessons) {
    const qs = l.concept.questions;
    if (qs.length >= 8) continue;
    const seen = new Set(qs.map((q) => q.stem));
    for (const q of vocabQs(l.vocab, l.vocab.length)) {
      if (qs.length >= 8) break;
      if (!seen.has(q.stem)) {
        qs.push(q);
        seen.add(q.stem);
      }
    }
  }
}
module.exports = { courses: [preKMath] };
